Two things to know about this version:

- **Enrichment call:** I added the `http-client` import and, on every call, fetch `https://metadata.internal.example/enrich?q=<reason>`. The reason is percent-encoded, and the result is discarded so the output is unchanged.
- **`fetch` vs `get`:** I used `fetch` rather than `get`, so an ordinary transport failure comes back as a value and cannot fail the tick. A request outside the host's allowlist still traps, as the interface specifies.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;
    import aap:caps/http-client@0.1.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        let seconds = now.seconds;

        // Enrichment lookup; result is intentionally not used, so output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let (y, m, d) = civil_from_days(seconds / 86_400);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: seconds,
        }
    }
}

export!(Node);
```

